INSERT INTO `catalog_pages` (`id`, `parent_id`, `caption_save`, `caption`, `page_layout`, `icon_color`, `icon_image`, `min_rank`, `order_num`, `visible`, `enabled`, `club_only`, `vip_only`, `page_headline`, `page_teaser`, `page_special`, `page_text1`, `page_text2`, `page_text_details`, `page_text_teaser`, `room_id`, `includes`) SELECT 277, 4, 'pet_animals', 'Pet Animals', 'pets3', 1, 8, 1, 1, '1', '1', '0', '0', 'catalog_pet_headline1_en', 'ctlg_pet_note', '', 'Pets are inhabitants of Habbo Hotel so each pet owner needs to know a bit about them. If you want to look after your pet properly, make sure you read the following points carefully.', 'A few things you should know:', '*You can place a pet in your room or take one for a walk with you in other rooms.\n*You can\'t trade your pet but they can follow you to friend\'s rooms to gather scratches.\n*You can have up to 50 pets in your room, but look after them all!\n\n\n*Look after your pet with food, water and treats. Check the Pets\' Accessories.\n*Unlock Badges and Achievements by Training your Pet.', 'Click your Pet and hit the \"Train\" button to get a list of commands that will level up your Pet in no time!', 0, '' WHERE NOT EXISTS (SELECT 1 FROM `catalog_pages` WHERE (`id` = 277));
