INSERT INTO `catalog_pages` (`id`, `parent_id`, `caption_save`, `caption`, `page_layout`, `icon_color`, `icon_image`, `min_rank`, `order_num`, `visible`, `enabled`, `club_only`, `vip_only`, `page_headline`, `page_teaser`, `page_special`, `page_text1`, `page_text2`, `page_text_details`, `page_text_teaser`, `room_id`, `includes`) SELECT 222, 5, 'builders_club', 'Builders Club', 'pets3', 1, 28, 1, 1, '1', '1', '0', '0', 'block_header', 'ctlg_bclub_note', '', '1 Block... 2 Block... Red Block... Blue Block!', '1 Block... 2 Block... Red\r\nBlock... Blue Block!', '\r\n\r\nWith dozens of all the colours and patterns to choose from, you can really let your creativity run wild!\r\nExclusive to Builders Club.', '', 0, '' WHERE NOT EXISTS (SELECT 1 FROM `catalog_pages` WHERE (`id` = 222));
