INSERT INTO `catalog_pages` (`id`, `parent_id`, `caption_save`, `caption`, `page_layout`, `icon_color`, `icon_image`, `min_rank`, `order_num`, `visible`, `enabled`, `club_only`, `vip_only`, `page_headline`, `page_teaser`, `page_special`, `page_text1`, `page_text2`, `page_text_details`, `page_text_teaser`, `room_id`, `includes`) SELECT 224, 604, 'teleports', 'Teleports', 'default_3x3', 1, 120, 1, 8, '1', '1', '0', '0', 'catalog_doors_headline1', 'catalog_door_a', '', 'Beam yourself from one room to another with our space-age teleports. Buy a pair, put one in each room and you\'ve got your own suite! IMPORTANT: teleports are always sold in pairs except for the Random Banzai Teleport.', '', NULL, 'Click on an item for details.', 0, '' WHERE NOT EXISTS (SELECT 1 FROM `catalog_pages` WHERE (`id` = 224));
INSERT INTO `catalog_pages` (`id`, `parent_id`, `caption_save`, `caption`, `page_layout`, `icon_color`, `icon_image`, `min_rank`, `order_num`, `visible`, `enabled`, `club_only`, `vip_only`, `page_headline`, `page_teaser`, `page_special`, `page_text1`, `page_text2`, `page_text_details`, `page_text_teaser`, `room_id`, `includes`) SELECT 225, 604, 'trophies', 'Trophies', 'trophies', 1, 221, 1, 11, '1', '1', '0', '0', 'trophies', '', '', 'Everyone\'s a winner, baby! And now you can reward them all with our fabulous glittering array of bronze, silver and gold trophies.\n\nFirst choose the trophy model by click the arrows. Then select the metal. Type your inscription below and we\'ll engrave it on the trophy along with your name and today\'s date.\nRemember - it\'s permanent!', '', '', '', 0, '' WHERE NOT EXISTS (SELECT 1 FROM `catalog_pages` WHERE (`id` = 225));
