INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'owner', 'getOwnerName', 'equals_ignore_case', 'SELECT * FROM rooms WHERE owner_name LIKE ?' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'owner'));
INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'anything', 'filterAnything', 'contains', 'SELECT rooms.*, CONCAT_WS(rooms.owner_name, rooms.name, rooms.description, rooms.tags, guilds.name, guilds.description) as whole FROM rooms LEFT JOIN guilds ON rooms.guild_id = guilds.id HAVING whole LIKE ? ' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'anything'));
INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'roomname', 'getName', 'contains', 'SELECT * FROM rooms WHERE name COLLATE UTF8_GENERAL_CI LIKE ? ' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'roomname'));
INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'tag', 'getTags', 'equals', 'SELECT * FROM rooms WHERE tags LIKE CONCAT(?, \";%\") ' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'tag'));
INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'group', 'getGuildName', 'contains', 'SELECT rooms.* FROM guilds INNER JOIN rooms ON guilds.room_id = rooms.id WHERE CONCAT(guilds.name, guilds.description) LIKE ?' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'group'));
INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'desc', 'getDescription', 'contains', 'SELECT * FROM rooms WHERE description LIKE ?' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'desc'));
INSERT INTO `navigator_filter` (`key`, `field`, `compare`, `database_query`) SELECT 'promo', 'getPromotionDesc', 'contains', 'SELECT rooms.* FROM rooms INNER JOIN room_promotions ON rooms.id = room_promotions.id WHERE room_promotions.end_timestamp >= UNIX_TIMESTAMP() AND CONCAT (room_promotions.title, room_promotions.description) LIKE ?' WHERE NOT EXISTS (SELECT 1 FROM `navigator_filter` WHERE (`key` = 'promo'));
