-- Additiver Import des EMU-Dumps in eine bestehende MariaDB-Datenbank.
-- Hinweise und Grenzen siehe README.md. Vorher ein Backup erstellen.
SET NAMES utf8mb4;
SET @emu_previous_sql_mode = @@SESSION.sql_mode;
SET SESSION sql_mode = 'STRICT_ALL_TABLES,NO_ENGINE_SUBSTITUTION,NO_AUTO_VALUE_ON_ZERO';

-- Tabelle achievements
CREATE TABLE IF NOT EXISTS `achievements`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'ACH_',
  `category` enum('identity','explore','music','social','games','room_builder','pets','tools','events') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'identity',
  `level` int NOT NULL DEFAULT 1,
  `reward_amount` int NOT NULL DEFAULT 100,
  `reward_type` int NOT NULL DEFAULT 0,
  `points` int NULL DEFAULT 10,
  `progress_needed` int NOT NULL DEFAULT 1,
  PRIMARY KEY (`name`, `level`) USING BTREE,
  UNIQUE INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 2762 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;
SET @emu_ddl = IF(EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'achievements' AND COLUMN_NAME = 'id'), 'DO 0', 'ALTER TABLE `achievements` ADD COLUMN `id` int NOT NULL AUTO_INCREMENT UNIQUE');
PREPARE emu_stmt FROM @emu_ddl;
EXECUTE emu_stmt;
DEALLOCATE PREPARE emu_stmt;
ALTER TABLE `achievements`
  ADD COLUMN IF NOT EXISTS `name` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'ACH_',
  ADD COLUMN IF NOT EXISTS `category` enum('identity','explore','music','social','games','room_builder','pets','tools','events') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'identity',
  ADD COLUMN IF NOT EXISTS `level` int NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS `reward_amount` int NOT NULL DEFAULT 100,
  ADD COLUMN IF NOT EXISTS `reward_type` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `points` int NULL DEFAULT 10,
  ADD COLUMN IF NOT EXISTS `progress_needed` int NOT NULL DEFAULT 1;

