  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;
SET @emu_ddl = IF(EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'achievements_talents' AND COLUMN_NAME = 'id'), 'DO 0', 'ALTER TABLE `achievements_talents` ADD COLUMN `id` int NOT NULL AUTO_INCREMENT UNIQUE');
PREPARE emu_stmt FROM @emu_ddl;
EXECUTE emu_stmt;
DEALLOCATE PREPARE emu_stmt;
ALTER TABLE `achievements_talents`
  ADD COLUMN IF NOT EXISTS `type` enum('citizenship','helper') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'citizenship',
  ADD COLUMN IF NOT EXISTS `level` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `achievement_ids` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `achievement_levels` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `reward_furni` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `reward_perks` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `reward_badges` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '';

-- Tabelle bans
CREATE TABLE IF NOT EXISTS `bans`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `ip` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `machine_id` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `user_staff_id` int NOT NULL,
  `timestamp` int NOT NULL,
  `ban_expire` int NOT NULL DEFAULT 0,
  `ban_reason` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `type` enum('account','ip','machine','super') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'account' COMMENT 'Account is the entry in the users table banned.\nIP is any client that connects with that IP.\nMachine is the computer that logged in.\nSuper is all of the above.',
  `cfh_topic` int NOT NULL DEFAULT -1,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `user_data`(`user_id` ASC, `ip` ASC, `machine_id` ASC, `ban_expire` ASC, `timestamp` ASC, `ban_reason` ASC) USING BTREE,
  INDEX `general`(`id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;
SET @emu_ddl = IF(EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'bans' AND COLUMN_NAME = 'id'), 'DO 0', 'ALTER TABLE `bans` ADD COLUMN `id` int NOT NULL AUTO_INCREMENT UNIQUE');
PREPARE emu_stmt FROM @emu_ddl;
EXECUTE emu_stmt;
DEALLOCATE PREPARE emu_stmt;
ALTER TABLE `bans`
  ADD COLUMN IF NOT EXISTS `user_id` int NOT NULL,
  ADD COLUMN IF NOT EXISTS `ip` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `machine_id` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `user_staff_id` int NOT NULL,
  ADD COLUMN IF NOT EXISTS `timestamp` int NOT NULL,
  ADD COLUMN IF NOT EXISTS `ban_expire` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `ban_reason` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `type` enum('account','ip','machine','super') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'account' COMMENT 'Account is the entry in the users table banned.\nIP is any client that connects with that IP.\nMachine is the computer that logged in.\nSuper is all of the above.',
  ADD COLUMN IF NOT EXISTS `cfh_topic` int NOT NULL DEFAULT -1;

