  ADD COLUMN IF NOT EXISTS `item` int NOT NULL;

-- Tabelle bots
CREATE TABLE IF NOT EXISTS `bots`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL DEFAULT 0,
  `room_id` int NOT NULL DEFAULT 0,
  `name` varchar(25) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `motto` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `figure` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `gender` enum('M','F') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'M',
  `x` int NOT NULL DEFAULT 0,
  `y` int NOT NULL DEFAULT 0,
  `z` double(11, 1) NOT NULL DEFAULT 0.0,
  `rot` int NOT NULL DEFAULT 0,
  `chat_lines` varchar(5112) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `chat_auto` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '1',
  `chat_random` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '1',
  `chat_delay` int NOT NULL DEFAULT 5,
  `dance` int NOT NULL DEFAULT 0,
  `freeroam` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0',
  `type` enum('generic','visitor_log','bartender','weapons_dealer') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'generic',
  `effect` int NOT NULL DEFAULT 0,
  `bubble_id` int NULL DEFAULT 31,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `general_data`(`id` ASC, `user_id` ASC, `room_id` ASC, `name` ASC, `motto` ASC, `gender` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;
SET @emu_ddl = IF(EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'bots' AND COLUMN_NAME = 'id'), 'DO 0', 'ALTER TABLE `bots` ADD COLUMN `id` int NOT NULL AUTO_INCREMENT UNIQUE');
PREPARE emu_stmt FROM @emu_ddl;
EXECUTE emu_stmt;
DEALLOCATE PREPARE emu_stmt;
ALTER TABLE `bots`
  ADD COLUMN IF NOT EXISTS `user_id` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `room_id` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `name` varchar(25) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `motto` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `figure` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `gender` enum('M','F') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'M',
  ADD COLUMN IF NOT EXISTS `x` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `y` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `z` double(11, 1) NOT NULL DEFAULT 0.0,
  ADD COLUMN IF NOT EXISTS `rot` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `chat_lines` varchar(5112) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `chat_auto` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '1',
  ADD COLUMN IF NOT EXISTS `chat_random` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '1',
  ADD COLUMN IF NOT EXISTS `chat_delay` int NOT NULL DEFAULT 5,
  ADD COLUMN IF NOT EXISTS `dance` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `freeroam` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0',
  ADD COLUMN IF NOT EXISTS `type` enum('generic','visitor_log','bartender','weapons_dealer') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'generic',
  ADD COLUMN IF NOT EXISTS `effect` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `bubble_id` int NULL DEFAULT 31;

