  ADD COLUMN IF NOT EXISTS `count` int NOT NULL,
  ADD COLUMN IF NOT EXISTS `prizes` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '179:1' COMMENT 'Used in the format of item_id:chance;item_id_2:chance. item_id must be id in the items_base table. Default value for chance is 100.',
  ADD COLUMN IF NOT EXISTS `achievement_tick` varchar(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  ADD COLUMN IF NOT EXISTS `achievement_cracked` varchar(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  ADD COLUMN IF NOT EXISTS `required_effect` int NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `subscription_duration` int NULL DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS `subscription_type` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL COMMENT 'hc for Habbo Club, bc for Builders Club';

