-- Tabelle pet_actions
CREATE TABLE IF NOT EXISTS `pet_actions`  (
  `ID` int NOT NULL AUTO_INCREMENT,
  `pet_type` int NOT NULL,
  `pet_name` varchar(32) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `offspring_type` int NOT NULL DEFAULT -1,
  `happy_actions` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `tired_actions` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `random_actions` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `can_swim` enum('1','0') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '0',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 77 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;
SET @emu_ddl = IF(EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'pet_actions' AND COLUMN_NAME = 'ID'), 'DO 0', 'ALTER TABLE `pet_actions` ADD COLUMN `ID` int NOT NULL AUTO_INCREMENT UNIQUE');
PREPARE emu_stmt FROM @emu_ddl;
EXECUTE emu_stmt;
DEALLOCATE PREPARE emu_stmt;
ALTER TABLE `pet_actions`
  ADD COLUMN IF NOT EXISTS `pet_type` int NOT NULL,
  ADD COLUMN IF NOT EXISTS `pet_name` varchar(32) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  ADD COLUMN IF NOT EXISTS `offspring_type` int NOT NULL DEFAULT -1,
  ADD COLUMN IF NOT EXISTS `happy_actions` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `tired_actions` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `random_actions` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `can_swim` enum('1','0') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '0';

