-- Tabelle wordfilter
CREATE TABLE IF NOT EXISTS `wordfilter`  (
  `key` varchar(256) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'The word to filter.',
  `replacement` varchar(16) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'What the word should be replaced with.',
  `hide` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0' COMMENT 'Wether the whole message that contains this word should be hidden from being displayed.',
  `report` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0' COMMENT 'Wether the message should be reported as auto-report to the moderators.',
  `mute` int NOT NULL DEFAULT 0 COMMENT 'Time user gets muted for mentioning this word.',
  UNIQUE INDEX `key`(`key`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;
ALTER TABLE `wordfilter`
  ADD COLUMN IF NOT EXISTS `key` varchar(256) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'The word to filter.',
  ADD COLUMN IF NOT EXISTS `replacement` varchar(16) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'What the word should be replaced with.',
  ADD COLUMN IF NOT EXISTS `hide` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0' COMMENT 'Wether the whole message that contains this word should be hidden from being displayed.',
  ADD COLUMN IF NOT EXISTS `report` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0' COMMENT 'Wether the message should be reported as auto-report to the moderators.',
  ADD COLUMN IF NOT EXISTS `mute` int NOT NULL DEFAULT 0 COMMENT 'Time user gets muted for mentioning this word.';

